import pathlib,json,hashlib,statistics,shutil
p=pathlib.Path('/home/vrondelli/projects/cyberAlchemy-v2/implementation/agent-reasoning-engine/benchmarks/glm-episodes-v1/evidence/contract-loop-2026-09-07')
trials=[];sources=None
for batch in ['iteration-01','confirmation-01']:
 m=json.loads((p/batch/'manifest.json').read_text());r=json.loads((p/batch/'result.json').read_text());assert r['status']=='COMPLETED'
 if sources is None:sources=m['sources']
 assert sources==m['sources']
 assert r['planned']==len(m['schedule'])==len(r['trials'])
 for t in r['trials']:
  a=t['report']['arms'][0];c=json.loads((p/batch/f"trial-{t['index']:02d}/arm-0/completed.json").read_text());head=[d['soft_headroom_tokens'] for d in c['dispatch_headroom']];assert head and min(head)>0
  trials.append({'batch':batch,'index':t['index'],'pair':t['repetition'],'policy':t['policy'],'repair':a['verified_repair'],'continuity':a['continuity']['passed'],'joint':a['verified_repair'] and a['continuity']['passed'],'minimum_soft_headroom':min(head),'elapsed_ms':a['elapsed_ms'],'recycles':c['recycles'],'metrics':t['report']['totals'],'evidence_ref':f"{batch}/trial-{t['index']:02d}/checked-report.json"})
for s in sources:assert hashlib.sha256(pathlib.Path(s['path']).read_bytes()).hexdigest()==s['sha256']
pairs=[];streak=0
for n in sorted(set(t['pair'] for t in trials)):
 ts=[t for t in trials if t['pair']==n];assert len(ts)==2 and set(t['policy'] for t in ts)=={'clear-v1','recent-observations-v2'}
 passed=all(t['joint'] for t in ts);streak=streak+1 if passed else 0;pairs.append({'pair':n,'joint_pass':passed})
summary={'authority_effect':'none','target_met':streak>=3,'consecutive_passing_pairs':streak,'trials':trials,'pairs':pairs,'total_trials':len(trials),'repairs':sum(t['repair'] for t in trials),'continuity_passes':sum(t['continuity'] for t in trials),'minimum_soft_headroom':min(t['minimum_soft_headroom'] for t in trials),'model_attempts':sum(t['metrics']['model_attempts'] for t in trials),'tokenizer_attempts':sum(t['metrics']['tokenizer_attempts'] for t in trials),'input_tokens':sum(t['metrics']['input_tokens'] for t in trials),'output_tokens':sum(t['metrics']['output_tokens'] for t in trials),'median_arm_ms':statistics.median(t['elapsed_ms'] for t in trials),'adaptive_stopping':True,'failure_replacement':False,'sources_unchanged':True,'open_questions_ref':'README.md#open-questions'}
assert summary['target_met'];(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
validation={'authority_effect':'none','status':'PASS','local_tests':{'passed':362,'failed':0,'log':'tests.tap'},'source_hashes_verified':True,'sources':sources,'live_trial_count':len(trials),'consecutive_joint_passing_pairs':streak,'defaults_changed':False,'claim_ceiling':'Adaptive same-task validation, not unbiased reliability or provider-internal compaction proof','open_questions_ref':'README.md#open-questions'}
(p/'validation.json').write_text(json.dumps(validation,indent=2)+'\n');shutil.copyfile('/tmp/are-loop-tests.tap',p/'tests.tap');shutil.copyfile('/tmp/summarize-contract-loop.py',p/'summarize.py')
lines=['# Compact contract loop — 2026-09-07','',f"Target reached: {streak} consecutive paired repair-and-continuity passes at soft limit8000. Overall {summary['repairs']}/{len(trials)} repairs and {summary['continuity_passes']}/{len(trials)} continuity passes. The failed first repair remains counted.",'','## Implementation','','Opt-in compact-contract-v5 shortens v4 contract guidance and two repeated completion explanations. It preserves the exact patch schema, strict rejection diagnostics, required recovery, native delivery accounting, fixture/oracle, output reserve2048, token margin256, hard16384 and soft8000. Existing policies and defaults remain unchanged. The pre-freeze [362-test suite](tests.tap) passed without failures, including prompt-size reduction and malformed-candidate rejection without retries.','','The previous v4 fresh request measured5754 input tokens: with reserve and margin it exceeded8000 by58. Every dispatch in this loop fit its limit. However, minimum measured headroom was only '+str(summary['minimum_soft_headroom'])+' tokens: this remains a narrow candidate budget, not broad robustness evidence.','','## Every trial','','| Pair | Policy | Repair | Continuity | Minimum soft headroom | Evidence |','| ---: | --- | --- | --- | ---: | --- |']
for t in trials:lines.append(f"| {t['pair']} | {t['policy']} | {t['repair']} | {t['continuity']} | {t['minimum_soft_headroom']} | [Report]({t['evidence_ref']}) |")
lines+=['','The first clear-v1 patch passed7/8 oracle checks but missed positional ordering. All subsequent patches passed8/8. Continuity requires all prescribed reads/delivery, actual recycling and meaningful archive recovery.','','## Experiment boundaries','',f"Used {summary['model_attempts']} model and {summary['tokenizer_attempts']} tokenizer attempts; recorded input/output tokens {summary['input_tokens']}/{summary['output_tokens']}. Median arm time {summary['median_arm_ms']/1000:.1f}s.",'','The [plan](PLAN.md) defined the target. [Iteration01](iteration-01/manifest.json) froze six trials. After pairs2/3 passed, a separately [predeclared confirmation pair](confirmation-01/PLAN.md) used identical frozen source hashes and task bytes. Pair4 passed, satisfying the consecutive-pair target. This is adaptive stopping on the same task; neither the streak nor7/8 is an unbiased reliability estimate. No failed trial was replaced or automatically retried.','','Source hashes matched across both batches and at aggregation ([validation](validation.json)). Checked reports validate recorded integrity/accounting and oracle receipts; they are not fresh oracle replays or cryptographic authenticity proofs. Exact raw inputs remain under /tmp/are-glm-contract-loop-01 and /tmp/are-glm-contract-confirmation-01. Exported visible traces omit raw message history/provider reasoning. These subset exports are not standalone report inputs. Request admission and recycling measurements cannot prove absence of provider-internal compaction.','','## Open Questions','','- Can we increase the 30-token minimum headroom without removing useful evidence?','- Does the candidate generalize to held-out tasks and longer contexts?','- Will controlled, non-adaptive repetitions confirm the apparent improvement?','- Can a separately frozen longer fixture exercise continuity at12K?','']
(p/'README.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in summary.items() if k not in ['trials','pairs']},indent=2))
